    int64_t idx = z_t4804_find(_this, _key, h, &slot);
    z_t1470_t _r = {0};
    if (idx < 0) {
        _r.tag = Z_OPTION_STRING_TAG_NONE;
        _r.data = NULL;
        return _r;
    }
    _r.tag = Z_OPTION_STRING_TAG_SOME;
    z_t59_t* _box = (z_t59_t*)z_xmalloc(sizeof(z_t59_t));
    *_box = _this->entries[idx].value;
    _r.data = _box;
